cases.text:
board B {
  use library "tiny";
  import lib "github.com/x/y";
  component R1: RESISTOR { value = 10kohm; tol = -1.5; big = 123456789012345678901234567890; f = 0.1; on = true; off = false; pin = U1.A; s = "q\"\n\t\\"; }
  component C1: lib.parts.CAP;
  port VIN: power_in;
  module SUB: lib.Sub;
  net N1 { R1.1; SUB.VIN.X; }
  no_connect U1.NC1, U1.NC2 { reason = "unused"; }
  no_connect U1.NC3;
  supply VIN { voltage = 3.3V; external = true; }
  interface BUS: i2c { speed = 400kHz; bind U1 { SDA = PB7; SCL = PB6; } }
  constraint length_match(N1, SUB/U2/U3.PIN, X.Y) { tolerance = +0.5mm; }
  constraint keepout() { }
  configure U1.USART1 as console { TX = PA9; }
  power_state SLEEP { VIN = off; }
  physical_macro BUCK: layout on SUB { member "U1" = U1; net VIN = port.VIN; }
  physical_macro PLAIN: lib.Def { }
  mechanical {
    outline rectangle { size = (50mm, 40mm); corner_radius = 1mm; }
    cutout c1 polygon { points = [(0mm, 0mm), (1mm, 0mm), (-1mm, -2.5mm)]; }
    hole h1 { at = (5mm, 5mm); diameter = 3.2mm; }
    rules { clearance = 0.2mm; }
    stackup { copper F.Cu { thickness = 35um; } dielectric core { er = 4.5; } }
    use lib.profiles.Pi as pi { offset = 1mm; }
    use lib.profiles.Hat { }
  }
  silkscreen { branding { enabled = false; } text t1 { value = "Hi"; at = (1mm, 2mm); } }
}

device D {
  vendor = "ST";
  pad PA0 { ball = A1; }
  power_domain VDD { min = 1.7V; }
  peripheral USART1: uart { signal TX: output; signal RX: input { pull = up; } }
  mux PA9: USART1.TX { af = 7; }
  resource DMA1;
  unit U: lib.Kind { a = PA0; }
  group G: diff.pair { p = PA1; }
  mode_group M { x = 1; }
  pad_set S { pads = "PA0,PA1"; }
  route USART1.TX { max_length = 10mm; }
}

macro M {
  import fp "x/y.kicad_mod";
  version = 1;
  evidence = { source = "datasheet"; pages = [1, 2]; ref = U.1; nested = { k = (1, -2mm); }; };
  list = [];
  tuple = ();
  pad U.1 = VIN;
  pad "U2"."EP" = "GND";
  isolated U.3;
  net VIN;
  member U { footprint = fp; at = (1mm, 2mm); contact c1 { pad = U.1; } contact = 5; }
  silkscreen S { }
}

board_profile Pi {
  connector J1 { at = (3.5mm, 3.5mm); }
  outline rectangle { size = (85mm, 56mm); }
  use other.P as q { }
}
